final class BubbleSortDemo {
    private static final int[] SAMPLE_NUMBERS = {64, 34, 25, 12, 22, 11, 90};

    private BubbleSortDemo() {
    }

    static void run() {
        int[] numbers = SAMPLE_NUMBERS.clone();

        BubbleSort.sort(numbers);

        System.out.println("Sorted array: ");
        System.out.println(IntArrayFormatter.format(numbers));
    }
}

final class BubbleSort {
    private BubbleSort() {
    }

    static void sort(int[] numbers) {
        if (numbers == null || numbers.length < 2) {
            return;
        }

        for (int pass = 0; pass < numbers.length - 1; pass++) {
            boolean swapped = moveLargestRemainingValue(numbers, pass);

            if (!swapped) {
                return;
            }
        }
    }

    private static boolean moveLargestRemainingValue(int[] numbers, int pass) {
        boolean swapped = false;
        int unsortedLimit = numbers.length - pass - 1;

        for (int index = 0; index < unsortedLimit; index++) {
            if (numbers[index] > numbers[index + 1]) {
                swap(numbers, index, index + 1);
                swapped = true;
            }
        }

        return swapped;
    }

    private static void swap(int[] numbers, int firstIndex, int secondIndex) {
        int temp = numbers[firstIndex];
        numbers[firstIndex] = numbers[secondIndex];
        numbers[secondIndex] = temp;
    }
}

class GFG {
    public static void main(String[] args) {
        BubbleSortDemo.run();
    }
}

final class IntArrayFormatter {
    private IntArrayFormatter() {
    }

    static String format(int[] numbers) {
        if (numbers == null || numbers.length == 0) {
            return "";
        }

        StringBuilder output = new StringBuilder();
        for (int number : numbers) {
            output.append(number).append(' ');
        }

        return output.toString();
    }
}
